    const [category, setCategory] = useState(ALL_CATEGORIES);
    const [actor, setActor] = useState(EVERYONE);
    const [query, setQuery] = useState("");
    const [listFades, setListFades] = useState(false);
    const [selected, setSelected] = useState<AuditEvent | null>(null);
    const [dialogOpen, setDialogOpen] = useState(false);
    const filtered = useMemo(() => {
        const needle = query.trim().toLowerCase();
        return EVENTS.filter((event) => (actor === EVERYONE || event.actor.id === actor) &&
            (needle === "" || (SEARCH_INDEX.get(event.id) ?? "").includes(needle)));
    }, [actor, query]);
    const counts = CATEGORIES.map((item) => item === ALL_CATEGORIES ? filtered.length : filtered.filter((event) => event.category === item).length);
