        <div>
          <div className="art:mb-5 art:flex art:flex-wrap art:items-center art:gap-3">
            <div className="art:max-w-full art:overflow-x-auto art:p-1">
              <CategoryTabs idPrefix={id} categories={CATEGORIES} counts={counts} value={category} onValueChange={selectTab}/>
            </div>
            <div className="art:flex art:w-full art:flex-wrap art:items-center art:gap-2 art:@min-[640px]/artemis:ml-auto art:@min-[640px]/artemis:w-auto">
              <ActorSelect value={actor} onChange={setActor} options={ACTOR_OPTIONS}/>
              <SearchField value={query} onChange={setQuery} onClear={clearSearch} inputRef={searchRef}/>
            </div>
          </div>
          <div id={`${id}-events`} role="tabpanel" aria-labelledby={`${id}-category-${categoryIndex}`} className="art:max-h-144 art:overflow-y-auto art:overscroll-contain art:px-1">
            <motion.div key={category} className="art:min-h-96" initial={listFades && !reduce ? { opacity: 0 } : false} animate={{ opacity: 1 }} transition={LIST_FADE}>
              {groups.length === 0 ? (<EmptyState onClear={clearFilters}/>) : (groups.map((group) => (<section key={group.day.id} className="art:mb-5 art:last:mb-0">
                    <h3 className="art:flex art:items-center art:gap-3 art:px-3 art:py-2 art:text-xs art:font-medium art:text-muted-foreground art:@min-[640px]/artemis:px-4">
