                      <span className="art:tabular-nums">{group.events.length}</span>
                    </h3>
                    <ol className="art:divide-y art:divide-border/60">
                      {group.events.map((event) => (<EventRow key={event.id} event={event} onOpen={openEvent}/>))}
                    </ol>
                  </section>)))}
            </motion.div>
          </div>
        </div>
        <output aria-live="polite" className="art:sr-only">
          {visible.length} matching {visible.length === 1 ? "event" : "events"}.
        </output>
        <EventDialog event={selected} open={dialogOpen} onClose={() => setDialogOpen(false)}/>
      </section>
    </HintTooltipHost>);
}

