export const EMPTY_VALUE = "Not set";
export const ALL_CATEGORIES = "All";
export const EVERYONE = "everyone";
function unique<T, K>(items: readonly T[], key: (item: T) => K): T[] {
    const seen = new Set<K>();
    const out: T[] = [];
    for (const item of items) {
        const k = key(item);
        if (seen.has(k))
            continue;
        seen.add(k);
        out.push(item);
    }
    return out;
}
export function categoriesOf(events: readonly AuditEvent[]): string[] {
    return [ALL_CATEGORIES, ...unique(events, (e) => e.category).map((e) => e.category)];
}
export function actorsOf(events: readonly AuditEvent[]): AuditActor[] {
    return unique(events, (e) => e.actor.id).map((e) => e.actor);
}
export function searchText(event: AuditEvent): string {
    return [
        event.id,
        event.actor.name,
        event.action,
        event.target,
        event.category,
        event.description,
        ...event.changes.flatMap((change) => [change.label, change.before, change.after]),
        ...event.metadata.flatMap((item) => [item.label, item.value]),
    ]
        .filter((part): part is string => Boolean(part))
        .join(" ")
        .toLowerCase();
}
export type DayGroup = {
    day: AuditDay;
    events: AuditEvent[];
};
export function groupByDay(events: readonly AuditEvent[]): DayGroup[] {
    const groups: DayGroup[] = [];
    for (const event of events) {
        const last = groups[groups.length - 1];
        if (last && last.day.id === event.day.id)
            last.events.push(event);
        else
            groups.push({ day: event.day, events: [event] });
    }
    return groups;
}

