type CopyState = "idle" | "copied" | "failed";
function CopyEventId({ id }: {
    id: string;
}) {
    const [state, setState] = useState<CopyState>("idle");
    const copy = async () => {
        try {
            if (!navigator.clipboard)
                throw new Error("Clipboard unavailable");
            await navigator.clipboard.writeText(id);
            setState("copied");
        }
        catch {
            setState("failed");
        }
    };
    return (<>
      <HintTooltip content="Copy event ID">
        <ArtemisButton variant="ghost" size="icon" className="art:size-9" aria-label="Copy event ID" onClick={copy}>
