        </ArtemisButton>
      </HintTooltip>
      <output aria-live="polite" className={state === "failed" ? "art:basis-full art:text-xs art:text-destructive" : "art:sr-only"}>
        {state === "copied" ? "Event ID copied." : state === "failed" ? "Couldn't copy. Select the ID to copy it manually." : null}
      </output>
    </>);
}
