        const clear = () => {
            if (timer.current !== null)
                window.clearTimeout(timer.current);
            timer.current = null;
        };
        return {
            show: (trigger, content, animated) => {
                clear();
                const current = hintRef.current;
                if (current?.open && current.trigger === trigger)
                    return;
                setHint({ trigger, content, animated, open: true });
            },
            hide: (trigger, delay) => {
                const current = hintRef.current;
                if (!current?.open || current.trigger !== trigger)
                    return;
                clear();
                const close = () => {
                    timer.current = null;
                    setHint((h) => (h && h.trigger === trigger ? { ...h, open: false } : h));
                };
                if (delay > 0)
                    timer.current = window.setTimeout(close, delay);
                else
                    close();
            },
            isOpen: (trigger) => Boolean(hintRef.current?.open && hintRef.current.trigger === trigger),
        };
    }, []);
