        if (api.isOpen(trigger)) {
            api.show(trigger, content, !reduce);
            return;
        }
        openTimer.current = window.setTimeout(() => {
            openTimer.current = null;
            api.show(trigger, content, !reduce);
        }, OPEN_DELAY);
    };
    const onPointerLeave = () => {
        clearOpenTimer();
        if (triggerRef.current)
            api.hide(triggerRef.current, CLOSE_DELAY);
    };
